        n_init = 200

    best_h = project_feasible(h_init, n_init)
    best_c = compute_c5(best_h, n_init)
    best_n = n_init

    # Phase 1: Intensively optimize parent
    t1 = min(t0 + 200, deadline - 400)
    best_h, best_c = full_lbfgs(best_h, best_n, t1)
    if time.time() < deadline - 300:
        t1b = min(time.time() + 60, deadline - 300)
        h, c = slsqp_run(best_h, best_n, t1b, alpha=1000000, maxiter=4000)
        if c < best_c:
            best_c = c
            best_h = h

    # Phase 2: Try larger n values (key for breaking the barrier)
    for n_try in [400, 500]:
        if time.time() > deadline - 300:
            break
        x_old = np.linspace(0, 2, best_n, endpoint=False)
        x_new = np.linspace(0, 2, n_try, endpoint=False)
        h_interp = np.interp(x_new, x_old, best_h)
        h_interp = project_feasible(h_interp, n_try)
        alloc = min(160, (deadline - time.time() - 150) * 0.55)
        if alloc < 35:
            continue
        h_t, c_t = full_lbfgs(h_interp, n_try, time.time() + alloc)
        if time.time() < deadline - 40:
            h_t, c_t = slsqp_run(h_t, n_try,
                                min(time.time() + 45, deadline - 30),
                                alpha=2000000, maxiter=4000)
        if c_t < best_c:
            best_c = c_t
            best_h = h_t
            best_n = n_try

    # Phase 3: Diverse restarts at best_n
    starts = [golden_ratio_start(best_n),
              random_binary_start(best_n, rng),
              fourier_start(best_n, rng)]
    for s in starts:
        if time.time() > deadline - 100:
            break
        alloc = min(45, (deadline - time.time() - 40) * 0.4)
        if alloc < 15:
            break
        h_s, c_s = full_lbfgs(s, best_n, time.time() + alloc * 0.7)
        if c_s < best_c:
            best_c = c_s
            best_h = h_s

    # Phase 4: Restart with perturbation of current best
    if time.time() < deadline - 80:
        h_pert = best_h + rng.randn(best_n) * 0.05
        h_pert = project_feasible(h_pert, best_n)
        alloc = min(50, (deadline - time.time() - 25) * 0.5)
        if alloc > 15:
            h_p, c_p = full_lbfgs(h_pert, best_n, time.time() + alloc * 0.6)
            if c_p < best_c:
                best_c = c_p
                best_h = h_p

    # Phase 5: Final SLSQP polish
    if time.time() < deadline - 25:
        t5 = min(time.time() + 50, deadline - 12)
        h_f, c_f = slsqp_run(best_h, best_n, t5, alpha=5000000, maxiter=5000)
        if c_f < best_c:
            best_c = c_f
            best_h = h_f

    # Phase 6: Gradient-directed local search
    if time.time() < deadline - 10:
        t6 = min(time.time() + 40, deadline - 4)
        best_h, best_c = gradient_directed_search(best_h, best_n, t6, step=0.001)

    # Phase 7: Pair polish
    if time.time() < deadline - 2:
        best_h, best_c = pair_polish(best_h, best_n, deadline - 1, radius=40)

    best_h = project_feasible(best_h, best_n)
    best_c = compute_c5(best_h, best_n)
    return best_h, best_c, best_n
